"""Intent tests for M1-T27: the full-grid convolutional network of the DQN agent (AGENT-05, AD-05)."""

import dataclasses
import importlib.util
import sys
from collections.abc import Iterator, Mapping
from pathlib import Path
from typing import Any

import numpy as np
import pytest
import torch

from rllab.agents import DQNAgent
from rllab.core import SOLO, ActionSpace, AgentParams, Exploration, TeamSpec, Transition

KIT_PATH = Path(__file__).resolve().parents[2] / "contracts" / "kit.py"
_spec = importlib.util.spec_from_file_location("contract_kit", KIT_PATH)
assert _spec is not None and _spec.loader is not None
kit = importlib.util.module_from_spec(_spec)
sys.modules["contract_kit"] = kit
_spec.loader.exec_module(kit)

GRID_GAME = "grid_self_collision"


def _cnn_params(**changes: Any) -> AgentParams:
    base = kit.sample("core.AgentParams", "dqn_compact", AgentParams)
    return dataclasses.replace(base, net="cnn", **changes)


def _exploration() -> Exploration:
    return kit.sample("core.Exploration", "defaults", Exploration)


def _grid_env() -> Any:
    return kit.env_double("envs.Snake", GRID_GAME)


def _grid_team() -> TeamSpec:
    return _grid_env().teams[SOLO]


def _cnn_agent(**changes: Any) -> DQNAgent:
    return DQNAgent(_grid_team(), _cnn_params(**changes), _exploration(), seed=0)


def _tensors(state: Any) -> Iterator[torch.Tensor]:
    if isinstance(state, torch.Tensor):
        yield state
    elif isinstance(state, Mapping):
        for value in state.values():
            yield from _tensors(value)


def _weight_shapes(agent: DQNAgent, tmp_path: Path) -> list[tuple[int, ...]]:
    path = tmp_path / "checkpoint.pt"
    agent.save(path)
    state = torch.load(path, map_location="cpu", weights_only=True)
    return [tuple(t.shape) for t in _tensors(state)]


def _grid_transitions() -> list[Transition]:
    env = _grid_env()
    obs, _ = env.reset(env.seed)
    out = []
    for actions in env.recorded_actions:
        result = env.step(actions)
        done = np.asarray(result.done[SOLO], dtype=bool)
        out.append(
            Transition(
                obs=obs[SOLO],
                actions=actions[SOLO],
                reward=np.asarray(result.reward[SOLO], dtype=np.float32),
                next_obs=result.obs[SOLO],
                terminated=done if result.terminated else np.zeros_like(done),
                active=np.ones_like(done),
                truncated=bool(result.truncated),
            )
        )
        obs = result.obs
    return out


@pytest.mark.intent
def test_cnn_agent_on_grid_returns_one_of_three_actions() -> None:
    env = _grid_env()
    obs, _ = env.reset(env.seed)
    grid = obs[SOLO]
    assert grid.shape == (1, 3, 10, 10)
    agent = _cnn_agent()
    for explore in (False, True):
        out = np.asarray(agent.act(grid, explore=explore))
        assert out.shape == (1,)
        assert np.issubdtype(out.dtype, np.integer)
        assert 0 <= int(out[0]) < 3


@pytest.mark.intent
def test_cnn_agent_greedy_action_is_deterministic() -> None:
    env = _grid_env()
    obs, _ = env.reset(env.seed)
    agent = _cnn_agent()
    first = [int(np.asarray(agent.act(obs[SOLO], explore=False))[0]) for _ in range(5)]
    assert len(set(first)) == 1


