@pytest.mark.parametrize(
    "obs_shape",
    [(11,), (3, 10), (1, 3, 10, 10)],
    ids=["compact-1d", "2d", "4d"],
)
def test_cnn_rejects_non_3d_obs_shape(obs_shape: tuple[int, ...]) -> None:
    team = TeamSpec(n_agents=1, obs_shape=obs_shape, actions=ActionSpace("discrete", 3, 0))
