        assert t.next_obs.shape == (1, 3, 10, 10)
    agent = _cnn_agent(learn_start=2, batch_size=2, target_every=2)
    before = _weight_shapes(agent, tmp_path)
    for t in transitions * 3:
        out = np.asarray(agent.act(t.obs, explore=True))
        assert 0 <= int(out[0]) < 3
        agent.learn(t)
    after = _weight_shapes(agent, tmp_path)
    assert after == before
    greedy = int(np.asarray(agent.act(transitions[0].obs, explore=False))[0])
    assert 0 <= greedy < 3


@pytest.mark.intent
def test_cnn_agent_save_then_load_gives_same_greedy_actions(tmp_path: Path) -> None:
    transitions = _grid_transitions()
    agent = _cnn_agent(learn_start=2, batch_size=2)
    for t in transitions:
        agent.learn(t)
    path = tmp_path / "cnn.pt"
    agent.save(path)
    other = DQNAgent(_grid_team(), _cnn_params(learn_start=2, batch_size=2), _exploration(), seed=9)
    other.load(path)
    for t in transitions:
        a = np.asarray(agent.act(t.obs, explore=False))
        b = np.asarray(other.act(t.obs, explore=False))
        assert np.array_equal(a, b)

