"""Intent tests for M1-T27: the full-grid convolutional network of the DQN agent (AGENT-05, AD-05).

AD-05: with `net="cnn"` the agent's network is two 3x3 convolutions (16 then 32 channels) and one
128-unit hidden layer over the 3x10x10 head/body/food grid. The checkpoint is a PyTorch state dict,
so the layer shapes are read back from `save`.
"""

import dataclasses
import importlib.util
import sys
from collections.abc import Iterator, Mapping
from pathlib import Path
from typing import Any

import numpy as np
import pytest
import torch

from rllab.agents import DQNAgent
