assert _spec.loader is not None
kit = importlib.util.module_from_spec(_spec)
sys.modules["contract_kit"] = kit
_spec.loader.exec_module(kit)

GRID_GAME = "grid_self_collision"
CONVS = {(16, 3, 3, 3), (32, 16, 3, 3)}
SHAPE_ERROR = r"(?i)cnn|3-?d|obs_shape|shape"


def _cnn_params(**changes: Any) -> AgentParams:
    base = kit.sample("core.AgentParams", "dqn_compact", AgentParams)
    return dataclasses.replace(base, net="cnn", **changes)


def _exploration() -> Exploration:
    return kit.sample("core.Exploration", "defaults", Exploration)


def _grid_env() -> Any:
