    state = torch.load(path, map_location="cpu", weights_only=True)
    return [tuple(t.shape) for t in _tensors(state)]


def _assert_cnn(agent: DQNAgent, tmp_path: Path) -> None:
    shapes = _weight_shapes(agent, tmp_path)
    conv = {s for s in shapes if len(s) == 4}
    assert conv == CONVS
    linear = {s for s in shapes if len(s) == 2}
    hidden = {s for s in linear if s[0] == 128}
    assert len(hidden) == 1
    assert (3, 128) in linear
    assert linear == hidden | {(3, 128)}


